import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from divergingBar ----
/** US Census resident population, 2010 and 2019. A 24 row sample of the 52 row source. */
const statePopulation = [
  { state: 'California', pop2010: 37254523, pop2019: 39512223 },
  { state: 'Texas', pop2010: 25145561, pop2019: 28995881 },
  { state: 'Florida', pop2010: 18801310, pop2019: 21477737 },
  { state: 'New York', pop2010: 19378102, pop2019: 19453561 },
  { state: 'Illinois', pop2010: 12830632, pop2019: 12671821 },
  { state: 'Ohio', pop2010: 11536504, pop2019: 11689100 },
  { state: 'Georgia', pop2010: 9687653, pop2019: 10617423 },
  { state: 'North Carolina', pop2010: 9535483, pop2019: 10488084 },
  { state: 'Washington', pop2010: 6724540, pop2019: 7614893 },
  { state: 'Arizona', pop2010: 6392017, pop2019: 7278717 },
  { state: 'Tennessee', pop2010: 6346105, pop2019: 6833174 },
  { state: 'Colorado', pop2010: 5029196, pop2019: 5758736 },
  { state: 'Minnesota', pop2010: 5303925, pop2019: 5639632 },
  { state: 'South Carolina', pop2010: 4625364, pop2019: 5148714 },
  { state: 'Connecticut', pop2010: 3574097, pop2019: 3565287 },
  { state: 'Utah', pop2010: 2763885, pop2019: 3205958 },
  { state: 'Puerto Rico', pop2010: 3725789, pop2019: 3193694 },
  { state: 'Iowa', pop2010: 3046355, pop2019: 3155070 },
  { state: 'Nevada', pop2010: 2700551, pop2019: 3080156 },
  { state: 'West Virginia', pop2010: 1852994, pop2019: 1792065 },
  { state: 'Idaho', pop2010: 1567582, pop2019: 1787147 },
  { state: 'Maine', pop2010: 1328361, pop2019: 1344212 },
  { state: 'District of Columbia', pop2010: 601723, pop2019: 705749 },
  { state: 'Vermont', pop2010: 625741, pop2019: 623989 }
];

/** One row per category, with the two counts whose relative change the bars encode. */
export type Data = { state: string; pop2010: number; pop2019: number }[];

const MARGIN = { top: 12, right: 56, bottom: 34, left: 24 };

// schemeRdBu[3] is [red, neutral, blue]; the neutral middle is unused here.
const NEGATIVE = d3.schemeRdBu[3][0];
const POSITIVE = d3.schemeRdBu[3][2];

const formatValue = d3.format('+.1%');
const formatTick = d3.format('+.0%');

export default function DivergingBarChart({
  data = statePopulation,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.8);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const rows = useMemo(
    () =>
      data
        .map((d) => ({ state: d.state, change: (d.pop2019 - d.pop2010) / d.pop2010 }))
        .sort((a, b) => b.change - a.change),
    [data]
  );

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([d3.min(rows, (d) => d.change) ?? 0, d3.max(rows, (d) => d.change) ?? 0])
        .nice()
        .range([0, innerWidth]),
    [rows, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleBand()
        .domain(rows.map((d) => d.state))
        .range([0, innerHeight])
        .padding(0.2),
    [rows, innerHeight]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(2, Math.round(innerWidth / 90)))
        .map((v) => ({ value: formatTick(v), offset: x(v) })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  const zero = x(0);

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Diverging bar chart of US state population change from 2010 to 2019">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {xTicks.map((t) => (
            <line key={t.value} className="grid" x1={t.offset} x2={t.offset} y1={0} y2={innerHeight} />
          ))}
        </g>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {rows.map((d) => {
          const isPositive = d.change > 0;
          const top = y(d.state) ?? 0;
          const middle = top + y.bandwidth() / 2;
          const end = x(d.change);
          return (
            <g key={d.state}>
              <rect
                x={Math.min(end, zero)}
                y={top}
                width={Math.abs(end - zero)}
                height={y.bandwidth()}
                fill={isPositive ? POSITIVE : NEGATIVE}
              />
              {/* Category label sits against the zero line, on the side opposite its own bar. */}
              <text
                x={zero + (isPositive ? -6 : 6)}
                y={middle}
                dy="0.32em"
                textAnchor={isPositive ? 'end' : 'start'}
                fill="var(--text)"
                fontSize={11}
              >
                {d.state}
              </text>
              <text
                x={end + (isPositive ? 4 : -4)}
                y={middle}
                dy="0.32em"
                textAnchor={isPositive ? 'start' : 'end'}
                fill="var(--muted)"
                fontSize={10}
              >
                {formatValue(d.change)}
              </text>
            </g>
          );
        })}
        <line x1={zero} x2={zero} y1={0} y2={innerHeight} stroke="var(--line)" />
      </g>
    </svg>
  );
}
